/* /* */ #if 0 //*/
fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() != 2 {
        eprintln!("Usage: program N");
        std::process::exit(1);
    }

    let n: u64 = match args[1].parse::<u64>() {
        Ok(value) => value,
        Err(_) => {
            eprintln!("Invalid N");
            std::process::exit(1);
        }
    };

    let mut a = "1".to_string();
    let mut b = "1".to_string();

    if n == 0 {
        println!("{}", a);
        return;
    }

    let mut i = 1u64;
    while i < n {
        let c = add_dec(&a, &b);
        a = b;
        b = c;
        i += 1;
    }

    println!("{}", b);
}

fn add_dec(x: &str, y: &str) -> String {
    let a: Vec<u8> = x.bytes().rev().map(|c| c - 48).collect();
    let b: Vec<u8> = y.bytes().rev().map(|c| c - 48).collect();
    let mut result: Vec<u8> = Vec::new();
    let mut carry = 0u8;
    let len = a.len().max(b.len());
    let mut i = 0usize;

    while i < len {
        let av = a.get(i).copied().unwrap_or(0);
        let bv = b.get(i).copied().unwrap_or(0);
        let sum = av + bv + carry;
        result.push(sum % 10);
        carry = sum / 10;
        i += 1;
    }

    if carry != 0 {
        result.push(carry);
    }

    result.iter().rev().map(|d| (*d + 48) as char).collect()
}
