string add_dec(const string& x, const string& y) {
    vector<uint8_t> a(x.rbegin(), x.rend());
    vector<uint8_t> b(y.rbegin(), y.rend());

    for (size_t i = 0; i < a.size(); ++i) a[i] -= static_cast<uint8_t>('0');
    for (size_t i = 0; i < b.size(); ++i) b[i] -= static_cast<uint8_t>('0');

    vector<uint8_t> result;
    size_t len = a.size() > b.size() ? a.size() : b.size();
    uint8_t carry = 0;

    for (size_t i = 0; i < len; ++i) {
        uint8_t av = i < a.size() ? a[i] : 0;
        uint8_t bv = i < b.size() ? b[i] : 0;
        uint8_t sum = av + bv + carry;
        result.push_back(sum % 10);
        carry = sum / 10;
    }

    if (carry) result.push_back(carry);

    string s;
    for (auto it = result.rbegin(); it != result.rend(); ++it) {
        s.push_back(static_cast<char>(*it + '0'));
    }
    return s;
}

int main(int argc, char** argv) {
    if (argc != 2) {
        fprintf(stderr, "Usage: program N\n");
        return 1;
    }

    char* end = nullptr;
    long long n = strtoll(argv[1], &end, 10);
    if (end == argv[1] || *end != '\0' || n < 0) {
        fprintf(stderr, "Invalid N\n");
        return 1;
    }

    string a = "1";
    string b = "1";

    if (n == 0) {
        printf("%s\n", a.c_str());
        return 0;
    }

    for (long long i = 1; i < n; ++i) {
        string c = add_dec(a, b);
        a = b;
        b = c;
    }

    printf("%s\n", b.c_str());
    return 0;
}
